import base64

def _t():
    from io import BytesIO, StringIO
    infp = BytesIO(b'd3d3LnB5dGhvbi5vcmc=')
    outfp = BytesIO()
    base64.decode(infp, outfp)
    assert outfp.getvalue() == b'www.python.org', ('assertEqual', outfp.getvalue(), b'www.python.org')
    try:
        base64.encode(*(StringIO('YWJj\n'), BytesIO()))
    except TypeError:
        pass
    try:
        base64.encode(*(BytesIO(b'YWJj\n'), StringIO()))
    except TypeError:
        pass
    try:
        base64.encode(*(StringIO('YWJj\n'), StringIO()))
    except TypeError:
        pass
try:
    _t()
except BaseException as _e:
    _oracle_write('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
